import test from 'node:test';
import assert from 'node:assert/strict';
import {correctProductData} from './product-title-corrections.mjs';
const row={id:'6Yj2zf1J51bnYAvt9ykY',titulo:'Sensor Infravermelho Automático Lixeira Retangular 16l Usb Branco',listing:'MLB5155902053'};
test('triagem57 exige identidade e preserva operação e afiliados com idempotência',()=>{const p={...row,preco:'99,99',linkAfiliado:'https://meli.la/preservado',variation_id:'original'},x=correctProductData(p);for(const k of Object.keys(p))assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{titulo:'Capa para '+row.titulo},{id:'outro'},{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'}])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');});
test('lixeira não transforma diâmetro em largura ou USB em autonomia comprovada',()=>{const x=correctProductData(row);assert.match(x.comentario,/não permite confirmar largura, profundidade ou altura/);assert.match(x.comentario,/não foi convertida em outra medida por suposição/);assert.match(x.comentario,/não esclarece sozinho alimentação, carregamento, bateria incluída ou autonomia/);assert.doesNotMatch(x.comentario,/basura/i);assert.doesNotMatch(x.pros,/23|diâmetro|recarregável|autonomia|impermeável|precisão/i);});
test('camisa mantém dados existentes sem nova edição',()=>{const p={id:'7cl224x4LF75c4vXGA5J',titulo:'Camisa Brasil 22 Patriota Algodao Unissex Direita Copa Hexa',comentario:'Dados do anúncio preservados'},x=correctProductData(p);for(const k of Object.keys(p))assert.equal(x[k],p[k]);});
test('pendrive mantém a revisão anterior sem nova versão da ficha',()=>{const p={id:'7CSQkSXeUHn9yzYR29hF',titulo:'Pen Drive 64gb Mini Usb 2.0 Chaveiro Metalico Resistente Alt Prateado Pen Drive',preco:'99,99',linkAfiliado:'https://meli.la/preservado'},x=correctProductData(p);assert.match(x.comentario,/não foram comprovados nesta análise/);assert.match(x.contras,/não foram testadas/);assert.deepEqual(correctProductData(x),x);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);});
